import { Request, Response } from 'express';
import mockjs from 'mockjs';
import getRowData from './mock_row_data';

// 测试服务器响应时间
const waitTime = (time: number = 100) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve(true);
    }, time);
  });
};

// 列表查询
function queryPager(req: Request, res: Response) {
  let rows: any[] = [];
  for (let i = 0; i < 20; i += 1) {
    rows.push(getRowData());
  }
  const returnData = {
    code: '200',
    desc: '',
    body: {
      rowCount: 20,
      rows: rows,
    },
  };
  return res.json(returnData);
}

// 列表查询
async function queryFpSpPage(req: Request, res: Response) {
  let rows: any[] = [];
  for (let i = 0; i < 10; i += 1) {
    rows.push(getRowData());
  }
  let returnData: any = {
    code: '200',
    desc: '操作成功',
    body: {rows}
  };
  return res.json(returnData);
}

// 操作成功
async function doSuccess(req: Request, res: Response) {
  const returnData = {
    code: '200',
    desc: '操作成功',
    body: null,
    msg: null,
    type: "",
  };
  await waitTime(500);
  return res.json(returnData);
}


